常见检测点检测 gmain 和 gum-js-loopfrida 在注入时, 会在目标进程下创建两个新线程，名为 gmain 和 gum-js-loop.通过检测线程名，可以判断当前进程是否被frida注入. 具体实现方法 可以通过判断 &#x2F;proc&#x2F;self&#x2F;task&#x2F;tid&#x2F;status 文件, status文件的第一行是线程名.遍历所有的线程名， 如果发现 gmain 和 gum-js-loop， 则可认定该进程被注入.下面给出检测代码
检测 gmain 和 gum-js-loopstatic const char *APPNAME = &quot;DetectFrida&quot;;static const char *FRIDA_THREAD_GUM_JS_LOOP = &quot;gum-js-loop&quot;;static const char *FRIDA_THREAD_GMAIN = &quot;gmain&quot;;static const char *FRIDA_NAMEDPIPE_LINJECTOR = &quot;linjector&quot;;static const char *PROC_MAPS = &quot;/proc/self/maps&quot;;static const char *PROC_STATUS = &quot;/proc/self/task/%s/status&quot;;static const char *PROC_FD = &quot;/proc/self/fd&quot;;static const char *PROC_TASK = &quot;/proc/self/task&quot;;__attribute__((always_inline))static inline void detect_frida_threads() &#123;    DIR *dir = opendir(PROC_TASK);    if (dir != NULL) &#123;        struct dirent *entry = NULL;        while ((entry = readdir(dir)) != NULL) &#123;            char filePath[MAX_LENGTH] = &quot;&quot;;            if (0 == my_strcmp(entry-&gt;d_name, &quot;.&quot;) || 0 == my_strcmp(entry-&gt;d_name, &quot;..&quot;)) &#123;                continue;            &#125;            snprintf(filePath, sizeof(filePath), PROC_STATUS, entry-&gt;d_name);            int fd = my_openat(AT_FDCWD, filePath, O_RDONLY | O_CLOEXEC, 0);            if (fd != 0) &#123;                char buf[MAX_LENGTH] = &quot;&quot;;                read_one_line(fd, buf, MAX_LENGTH);                if (my_strstr(buf, FRIDA_THREAD_GUM_JS_LOOP) ||                    my_strstr(buf, FRIDA_THREAD_GMAIN)) &#123;                    //Kill the thread. This freezes the app. Check if it is an anticpated behaviour                    //int tid = my_atoi(entry-&gt;d_name);                    //int ret = my_tgkill(getpid(), tid, SIGSTOP);                    __android_log_print(ANDROID_LOG_WARN, APPNAME,                                        &quot;Frida specific thread found. Act now!!!&quot;);                &#125;                my_close(fd);            &#125;        &#125;        closedir(dir);    &#125;&#125;

