d]&quot;, output,//                                    pElfSectArr-&gt;checksum[i]);                if (output != pElfSectArr-&gt;checksum[i]) &#123;                    __android_log_print(ANDROID_LOG_VERBOSE, APPNAME,                                        &quot;Executable Section Manipulated, &quot;                                        &quot;maybe due to Frida or other hooking framework.&quot;                                        &quot;Act Now!!!&quot;);                &#125;            &#125;        &#125; else &#123;            char ch[10] = &quot;&quot;, ch1[10] = &quot;&quot;;            __system_property_get(&quot;ro.build.version.release&quot;, ch);            __system_property_get(&quot;ro.system.build.version.release&quot;, ch1);            int version = my_atoi(ch);            int version1 = my_atoi(ch1);            if (version &lt; 10 || version1 &lt; 10) &#123;                __android_log_print(ANDROID_LOG_VERBOSE, APPNAME, &quot;Suspicious to get XOM in &quot;                                                                  &quot;version &lt; Android10&quot;);            &#125; else &#123;                if (0 == my_strncmp(libraryName, LIBC, my_strlen(LIBC))) &#123;                    //If it is not readable, then most likely it is not manipulated by Frida                    __android_log_print(ANDROID_LOG_VERBOSE, APPNAME, &quot;LIBC Executable Section&quot;                                                                      &quot; not readable! &quot;);                &#125; else &#123;                    __android_log_print(ANDROID_LOG_VERBOSE, APPNAME, &quot;Suspicious to get XOM &quot;                                                                      &quot;for non-system library on &quot;                                                                      &quot;Android 10 and above&quot;);                &#125;            &#125;        &#125;        return true;    &#125; else &#123;        if (buf[0] == &#x27;r&#x27;) &#123;           